corrected_code:
const express = require('express');
const db = require('../db');

const app = express();

app.get('/api/storage/deals/:dealId/manifest', async (req, res) => {
  const { dealId } = req.params;

  // Scope deal lookup to the authenticated account ID
  const deal = await db('filecoin_deals')
    .where({ deal_id: dealId, owner_account_id: req.user.accountId })
    .first();

  if (!deal) {
    return res.status(404).json({ error: 'Storage deal not found or access denied' });
  }

  return res.json({
    dealId: deal.deal_id,
    pieceCid: deal.piece_cid,
    provider: deal.storage_provider_address,
    fileManifest: deal.file_manifest,
    collateralSats: deal.collateral_amount
  });
});

module.exports = app;
